import gurobipy as gp
from gurobipy import GRB

# Parameters from statement
participants = ["P1", "P2", "P3"]
cars = ["C1", "C2", "C3"]
possible_assignments = [[1, 0, 1], [0, 1, 0], [1, 1, 1]]

model = gp.Model(env=env)

# Binary variables for allowed assignments
vars_mat = [[None] * len(cars) for _ in range(len(participants))]
for p_i in range(len(participants)):
    for c_j in range(len(cars)):
        if possible_assignments[p_i][c_j] == 1:
            vars_mat[p_i][c_j] = model.addVar(lb=0, ub=1, vtype=GRB.INTEGER, name=f"x_{participants[p_i]}_{cars[c_j]}")
        # else None (implicitly 0)

# Participant at most one car
for p_i in range(len(participants)):
    expr = gp.LinExpr()
    for c_j in range(len(cars)):
        if vars_mat[p_i][c_j] is not None:
            expr += vars_mat[p_i][c_j]
    model.addConstr(expr <= 1, name=f"part_{participants[p_i]}")

# Car at most one participant
for c_j in range(len(cars)):
    expr = gp.LinExpr()
    for p_i in range(len(participants)):
        if vars_mat[p_i][c_j] is not None:
            expr += vars_mat[p_i][c_j]
    model.addConstr(expr <= 1, name=f"car_{cars[c_j]}")

# Objective maximize total assignments
expr_obj = gp.LinExpr()
for p_i in range(len(participants)):
    for c_j in range(len(cars)):
        if vars_mat[p_i][c_j] is not None:
            expr_obj += vars_mat[p_i][c_j]
model.setObjective(expr_obj, GRB.MAXIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
